fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Optional: Check mask and a length equality, panic or handle gracefully if desired
    assert_eq!(a.len(), mask.len(), "Input and mask must be the same length");
    assert!(!values.is_empty(), "Replacement values array must be non-empty");

    let values_len = values.len();

    // Use iterator with enumerate to easily get the index
    a.into_iter()
        .enumerate()
        .map(|(i, elem)| {
            if mask[i] {
                values[i % values_len]
            } else {
                elem
            }
        })
        .collect()
}